"""Record layouts for interest. Generated by Séance from the COBOL record descriptions. Do not edit."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from seance.cobol_num import deedit, format_alpha, format_edited, format_numeric, parse_numeric

IN_WIDTH = 28
OUT_WIDTH = 33


@dataclass
class InRecord:
    acct_id: str
    balance: Decimal
    rate: Decimal
    days: Decimal

    @classmethod
    def parse(cls, line: str) -> "InRecord":
        line = line.ljust(28)
        return cls(
            acct_id=line[0:8].rstrip(),
            balance=parse_numeric(line[8:20], 11, 2, True, 'leading_sep'),
            rate=parse_numeric(line[20:25], 5, 4, False, 'none'),
            days=parse_numeric(line[25:28], 3, 0, False, 'none'),
        )

    def format(self) -> str:
        return (
            format_alpha(self.acct_id, 8)
            + format_numeric(self.balance, 11, 2, True, 'leading_sep')
            + format_numeric(self.rate, 5, 4, False, 'none')
            + format_numeric(self.days, 3, 0, False, 'none')
        ).rstrip()


@dataclass
class OutRecord:
    acct_id: str
    interest: Decimal
    new_bal: Decimal
    status: str

    @classmethod
    def parse(cls, line: str) -> "OutRecord":
        line = line.ljust(33)
        return cls(
            acct_id=line[0:8].rstrip(),
            interest=parse_numeric(line[8:20], 11, 2, True, 'leading_sep'),
            new_bal=parse_numeric(line[20:32], 11, 2, True, 'leading_sep'),
            status=line[32:33].rstrip(),
        )

    def format(self) -> str:
        return (
            format_alpha(self.acct_id, 8)
            + format_numeric(self.interest, 11, 2, True, 'leading_sep')
            + format_numeric(self.new_bal, 11, 2, True, 'leading_sep')
            + format_alpha(self.status, 1)
        ).rstrip()

